#include <stdint.h>

/* Field of 'ancho' bits starting at bit 'pos' of a 32-bit register. */
static inline uint32_t campo_lee(uint32_t reg, unsigned pos, unsigned ancho)
{
    uint32_t mascara = (ancho < 32u) ? ((1ul << ancho) - 1u) : 0xFFFFFFFFul;
    return (reg >> pos) & mascara;
}

static inline uint32_t campo_escribe(uint32_t reg, unsigned pos,
                                     unsigned ancho, uint32_t valor)
{
    uint32_t mascara = (ancho < 32u) ? ((1ul << ancho) - 1u) : 0xFFFFFFFFul;
    return (reg & ~(mascara << pos)) | ((valor & mascara) << pos);
}

