#include <avr/io.h>
#include <avr/interrupt.h>
#include <util/atomic.h>
#include <stdint.h>

static volatile uint16_t ticks;       /* written by the ISR */

ISR(TIMER0_COMPA_vect)
{
    ticks++;                          /* inside an ISR: no other ISR runs */
}

uint16_t ticks_lee(void)
{
    uint16_t copia;
    ATOMIC_BLOCK(ATOMIC_RESTORESTATE) {   /* cli ... restore SREG */
        copia = ticks;                    /* two bytes, one copy  */
    }
    return copia;
}

#include <stdbool.h>
#include <stdint.h>

/* Homing of the base (chapter 57): fast to the switch, back off,
   slow to the switch again. Called every millisecond; never blocks. */
typedef enum { BUSCA_RAPIDO, RETROCEDE, BUSCA_LENTO, HECHO, FALLO } fase_t;

typedef struct {
    fase_t   fase;
    uint32_t inicio;          /* ms when the current phase began */
} referencia_t;

/* Returns the speed to ask the stepper for (steps/s, < 0: backwards). */
int16_t referencia(referencia_t *r, bool final_carrera, uint32_t ahora)
{
    switch (r->fase) {
    case BUSCA_RAPIDO:
        if (final_carrera) { r->fase = RETROCEDE; r->inicio = ahora; }
        else if (ahora - r->inicio > 15000u) r->fase = FALLO;
        else return -800;
        return 0;
    case RETROCEDE:
        if (ahora - r->inicio >= 250u) { r->fase = BUSCA_LENTO; r->inicio = ahora; }
        return +400;
    case BUSCA_LENTO:
        if (final_carrera) { r->fase = HECHO; return 0; }
        if (ahora - r->inicio > 3000u) { r->fase = FALLO; return 0; }
        return -100;
    default:                  /* HECHO or FALLO: stopped */
        return 0;
    }
}

#include <stdbool.h>
#include <stdint.h>

#define TAM 64u                       /* a power of two */
#if (TAM & (TAM - 1u)) != 0
#error "TAM must be a power of two"
#endif

static uint8_t datos[TAM];
static volatile uint8_t cabeza;       /* written only by the producer */
static volatile uint8_t cola;         /* written only by the consumer */

bool bufer_pon(uint8_t x)             /* producer: e.g. the UART ISR */
{
    uint8_t c = cabeza;
    if ((uint8_t)(c - cola) == TAM) return false;    /* full */
    datos[c & (TAM - 1u)] = x;
    cabeza = (uint8_t)(c + 1u);       /* publish after writing */
    return true;
}

bool bufer_saca(uint8_t *x)           /* consumer: the main loop */
{
    uint8_t t = cola;
    if (t == cabeza) return false;    /* empty */
    *x = datos[t & (TAM - 1u)];
    cola = (uint8_t)(t + 1u);         /* free the slot after reading */
    return true;
}

#include <stdint.h>

typedef int32_t q16_t;                /* Q16.16: value = n / 65536 */
#define Q16(x) ((q16_t)((x) * 65536.0 + ((x) >= 0 ? 0.5 : -0.5)))

q16_t q16_mul(q16_t a, q16_t b)
{
    int64_t p = (int64_t)a * b;       /* Q32.32, never overflows   */
    p += (int64_t)1 << 15;            /* round to nearest          */
    p >>= 16;                         /* back to Q16.16            */
    if (p > INT32_MAX) return INT32_MAX;    /* saturate instead   */
    if (p < INT32_MIN) return INT32_MIN;    /* of wrapping around */
    return (q16_t)p;
}

#include <stdint.h>

uint8_t  a = 200, b = 100, e = 0x80;
uint8_t  c;   /* a + b             -> 44: the int 300, truncated  */
int      d;   /* a + b > 255       -> 1: compared as int          */
int      f;   /* ~e == 0x7F        -> 0: ~e is an int, 0xFF7F     */
uint32_t g;   /* 1000 * 60         -> int overflow on the AVR     */
uint32_t h;   /* 1000ul * 60       -> 60000 on every compiler     */
int      i;   /* -1 < 1u           -> 0: -1 becomes unsigned      */

void promocion(void)
{
    c = a + b;
    d = a + b > 255;
    f = ~e == 0x7F;
    g = 1000 * 60;
    h = 1000ul * 60;
    i = -1 < 1u;
}
